# Part A · Section 1 — cardiac cycle, Wiggers diagram, pressure–volume loop, muscle mechanics
TBL = ('<table style="border-collapse:collapse;margin:10px 0;font-size:14px"><tr>'
       + '{}' + '</tr></table>')
def hdr(*cols):
    return TBL.format(''.join(f'<th style="border:1px solid #bbb;padding:4px 10px;text-align:left">{c}</th>' for c in cols))

